fn add(take a: Int, take b: Int) -> Int {
    a + b
}

spec add {
    then add(40, 2) == 42;
    then add(-1, 1) == 0;
}

fn double(take x: Int) -> Int {
    x + x
}

spec double {
    then double(3) == 6;
    then double(0) == 0;
}

fn factorial(take n: Int) -> Int {
    if n <= 1 {
        1
    } else {
        n * factorial(n - 1)
    }
}

spec factorial {
    then factorial(0) == 1;
    then factorial(1) == 1;
    then factorial(5) == 120;
}

fn gcd(take a: Int, take b: Int) -> Int {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

spec gcd {
    then gcd(12, 8) == 4;
    then gcd(17, 5) == 1;
    then gcd(9, 0) == 9;
}

fn count_up(take n: Int) -> Int {
    var acc = 0;
    for i in 0..n {
        acc = acc + i;
    }
    acc
}

spec count_up {
    then count_up(0) == 0;
    then count_up(4) == 6;
}

fn largest(take xs: [Int; 4]) -> Int {
    var best = xs[0];
    for x in xs {
        if x > best {
            best = x;
        }
    }
    best
}

spec largest {
    then largest([3, 9, 2, 7]) == 9;
    then largest([5, 5, 5, 5]) == 5;
}

struct Point {
    x: Int,
    y: Int,
}

fn manhattan(in p: Point) -> Int {
    p.x + p.y
}

spec manhattan {
    then manhattan(Point { x: 3, y: 4 }) == 7;
    then manhattan(Point { x: 0, y: 0 }) == 0;
}

enum Dir {
    North,
    South,
    East,
    West,
}

fn code(take d: Dir) -> Int {
    match d {
        Dir::North => 0,
        Dir::East => 1,
        Dir::South => 2,
        Dir::West => 3,
    }
}

fn turn_right(take d: Dir) -> Dir {
    match d {
        Dir::North => Dir::East,
        Dir::East => Dir::South,
        Dir::South => Dir::West,
        Dir::West => Dir::North,
    }
}

spec turn_right {
    then code(turn_right(Dir::North)) == 1;
    then code(turn_right(Dir::West)) == 0;
}

fn safe_div(take a: Int, take b: Int) -> Option[Int] {
    if b == 0 {
        None
    } else {
        Some { value: a / b }
    }
}

fn or_zero(in o: Option[Int]) -> Int {
    match o {
        Some { value } => value,
        None => 0,
    }
}

spec safe_div {
    then or_zero(safe_div(10, 2)) == 5;
    then or_zero(safe_div(10, 0)) == 0;
}

struct Point {
    x: Int,
    y: Int,
}

fn is_origin(in p: Point) -> Bool {
    p.x == 0 && p.y == 0
}

spec is_origin {
    then is_origin(Point { x: 0, y: 0 });
    then is_origin(Point { x: 1, y: 0 }) == false;
}

fn average3(take a: F64, take b: F64, take c: F64) -> F64 {
    (a + b + c) / 3.0
}

fn is_two(take x: F64) -> Bool {
    x == 2.0
}

spec average3 {
    then is_two(average3(1.0, 2.0, 3.0));
    then average3(0.0, 0.0, 0.0) == 0.0;
}

fn first_or_zero() -> Int {
    var xs = std::array::empty();
    std::array::push(xs, 42);
    std::array::get(xs, 0)
}

spec first_or_zero {
    then first_or_zero() == 42;
}

module total;

fn sum(take xs: [Int; 4]) -> Int {
    var acc = 0;
    for x in xs {
        acc = acc + x;
    }
    acc
}

fn main() -> Int {
    sum([10, 20, 30, 40])
}

spec sum {
    then sum([1, 2, 3, 4]) == 10;
}
